import org.jetbrains.compose.resources.DrawableResource
import portfolio.app.shared.generated.resources.*

internal fun onboardingDocumentBounds(resource: DrawableResource): OnboardingImageBounds? = when (resource) {
    Res.drawable.onboarding_reports_dark -> OnboardingImageBounds(640, 760, 28, 60, 518, 642)
    Res.drawable.onboarding_reports_light -> OnboardingImageBounds(640, 760, 28, 60, 518, 642)
    else -> null
}
